  status?: string;
  priority?: string;
  faultType?: string;
  title?: string;
  description?: string;
  source?: string;
  recordedBy?: {
    userId?: string;
    name?: string;
    role?: string;
    deviceId?: string;
  };
  timestamps?: {
    recordedAt?: string;
    givenAt?: string;
    assignedAt?: string;
    crewArrivedAt?: string;
    completedAt?: string;
    deliveredAt?: string;
    approvedAt?: string;
  };
  location?: {
    areaLabel?: string;
    roadLabel?: string;
    zoneLabel?: string;
    nearestPipeId?: string;
    nearestPipeLabel?: string;
    nearestValveId?: string;
    nearestValveLabel?: string;
    pressureZoneId?: string;
    mapPath?: string;
    mapLinkStatus?: string;
  };
  contactName?: string;
  contactPhone?: string;
  audioTranscript?: {
    audioRefs?: string[];
    transcriptStatus?: string;
    transcriptText?: string;
  };
  evidence?: Array<{
    kind?: string;
    ref?: string;
  }>;
  approvalState?: string;
  aiChecks?: Array<{
    id?: string;
    severity?: string;
    category?: string;
    message?: string;
    suggestedAction?: string;
    resolved?: boolean;
  }>;
  managementMetrics?: {
    responseMinutes?: number;
    repairMinutes?: number;
    totalWorkMinutes?: number;
    estimatedWaterLoss?: string;
    estimatedCost?: string;
    repeatedFaultCountNearby?: number;
    highRiskArea?: boolean;
    reportTags?: string[];
  };
  recordLocked?: boolean;
  audit?: {
    storedPrivate?: boolean;
    visibleToFounderAdmin?: boolean;
    officialAfterApprovalOnly?: boolean;
    note?: string;
  };
};

